`CVTS_FUNC()` macros requests 5 arguments, 

https://github.com/opencv/opencv/blob/f5d82458014459e25830984c9ad9cbe182c4653c/3rdparty/carotene/src/convert_scale.cpp#L46-L50

In line 1251, `CVTS_FUNC()` macro is used with following arguments.

- (T1) `u16`
- (T2) `s8`
- (SIMD_SIZE) `16`
- (CVTINIT) `float32x4_t vscale = ... ; float32x4_t vshift = ... ;`
- (CVTROW) `{ for(size_t i = 0; i < w; i+= 8) ... }`

L1251 will be expanded/pre-processed with following code.

```cpp
#1251 "/home/kmtr/work/opencv/3rdparty/carotene/src/convert_scale.cpp"
void
convertScale(const Size2D & _size, const u16 * srcBase,
             ptrdiff_t srcStride, s8 * dstBase, ptrdiff_t dstStride,
             f64 alpha, f64 beta)
{
    internal::assertSupportedConfiguration();
    Size2D size(_size);
    if (srcStride == dstStride && srcStride == (ptrdiff_t) (size.width)) {
        size.width *= size.height;
        size.height = 1;
    }
    const ptrdiff_t sstep = srcStride / sizeof(u16);
    const ptrdiff_t dstep = dstStride / sizeof(s8);
    const size_t w = size.width & ~(16 - 1);
    if (size.width >= 16) {
        const u16 *_src = srcBase;
        s8 *_dst = dstBase;
        float32x4_t vscale = vdupq_n_f32((f32) alpha);
        float32x4_t vshift = vdupq_n_f32((f32) beta);
        for (ptrdiff_t h = size.height; h--; _src += sstep, _dst += dstep) {
            for (size_t i = 0; i < w; i += 8) {
                internal::prefetch(_src + i);
                uint16x8_t vline = vld1q_u16(_src + i);
                uint32x4_t vline1_u32 = vmovl_u16(vget_low_u16(vline));
                uint32x4_t vline2_u32 = vmovl_u16(vget_high_u16(vline));
                float32x4_t vline1_f32 = vcvtq_f32_u32(vline1_u32);
                float32x4_t vline2_f32 = vcvtq_f32_u32(vline2_u32);
                vline1_f32 = vmulq_f32(vline1_f32, vscale);
                vline2_f32 = vmulq_f32(vline2_f32, vscale);
                vline1_f32 = vaddq_f32(vline1_f32, vshift);
                vline2_f32 = vaddq_f32(vline2_f32, vshift);
                int32x4_t vline1_s32 =
                    internal::vroundq_s32_f32(vline1_f32);
                int32x4_t vline2_s32 =
                    internal::vroundq_s32_f32(vline2_f32);
                int16x4_t vRes1 = vqmovn_s32(vline1_s32);
                int16x4_t vRes2 = vqmovn_s32(vline2_s32);
                int8x8_t vRes = vqmovn_s16(vcombine_s16(vRes1, vRes2));
                vst1_s8(_dst + i, vRes);
    }}}
    if (w < size.width) {
        const u16 *_src = srcBase;
        s8 *_dst = dstBase;
        for (ptrdiff_t h = size.height; h--; _src += sstep, _dst += dstep)
            for (size_t i = w; i < size.width; i++)
                _dst[i] =
                    internal::saturate_cast < s8 >
                    (_src[i] * alpha + beta);
    }
